function validate([root, n, x]) {
  if (!Number.isInteger(n) || n < 1 || n > 100) return 'n is between 1 and 100.';
  if (n % 2 === 0) return 'n must be odd.';
  const values = root.filter(v => v !== null);
  if (values.length !== n) return 'The tree must have exactly n nodes.';
  const seen = new Set();
  for (const v of values) {
    if (!Number.isInteger(v) || v < 1 || v > n) return 'Every node value is between 1 and n.';
    if (seen.has(v)) return 'Node values must be distinct.';
    seen.add(v);
  }
  if (!Number.isInteger(x) || x < 1 || x > n) return 'x is between 1 and n.';
  return null;
}

