function btreeGameWinningMove(root, n, x) {
  let leftSize = 0;
  let rightSize = 0;

  function count(node) {
    if (node === null) {
      return 0;
    }
    const left = count(node.left);
    const right = count(node.right);
    if (node.val === x) {
      leftSize = left;
      rightSize = right;
    }
    return left + right + 1;
  }

  count(root);
  const parentSize = n - leftSize - rightSize - 1;
  const best = Math.max(leftSize, rightSize, parentSize);
  return best > n / 2;
}

