function btreeGameWinningMove(root, n, x) {
  // Build an undirected adjacency list, then try every y. With both players racing
  // along the x-y path, blue ends up with exactly the nodes strictly closer to y than to x.
  const adj = new Map();
  const stack = [root];
  while (stack.length) {
    const node = stack.pop();
    if (!adj.has(node.val)) adj.set(node.val, []);
    for (const child of [node.left, node.right]) {
      if (!child) continue;
      if (!adj.has(child.val)) adj.set(child.val, []);
      adj.get(node.val).push(child.val);
      adj.get(child.val).push(node.val);
      stack.push(child);
    }
  }
  const distances = start => {
    const dist = new Map([[start, 0]]);
    const queue = [start];
    for (let i = 0; i < queue.length; i++) {
      for (const next of adj.get(queue[i])) {
        if (!dist.has(next)) { dist.set(next, dist.get(queue[i]) + 1); queue.push(next); }
      }
    }
    return dist;
  };
  const fromX = distances(x);
  for (const y of adj.keys()) {
    if (y === x) continue;
    const fromY = distances(y);
    let blue = 0;
    for (const v of adj.keys()) if (fromY.get(v) < fromX.get(v)) blue++;
    if (blue > n - blue) return true;
  }
  return false;
}

