function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 61 + 2 * Math.floor(rand() * 20) : 1 + 2 * Math.floor(rand() * 8);
  // Some trees start with a long downward chain, which makes lopsided parts.
  const chain = rand() < 0.25 ? 1 + Math.floor(rand() * n) : 1;
  const nodes = [{ left: null, right: null }];
  for (let i = 1; i < chain; i++) {
    nodes[i - 1][rand() < 0.5 ? 'left' : 'right'] = i;
    nodes.push({ left: null, right: null });
  }
  const slots = [[chain - 1, 'left'], [chain - 1, 'right']];
  for (let i = chain; i < n; i++) {
    const k = Math.floor(rand() * slots.length);
    const [parent, side] = slots[k];
    slots[k] = slots[slots.length - 1];
    slots.pop();
    nodes[parent][side] = i;
    nodes.push({ left: null, right: null });
    slots.push([i, 'left'], [i, 'right']);
  }
  // Values 1..n in a random order.
  const values = Array.from({ length: n }, (_, i) => i + 1);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [values[i], values[j]] = [values[j], values[i]];
  }
  // Level-order serialisation with null for missing children, trailing nulls removed.
  const out = [];
  const queue = [0];
  for (let q = 0; q < queue.length; q++) {
    if (queue[q] === null) { out.push(null); continue; }
    out.push(values[queue[q]]);
    queue.push(nodes[queue[q]].left, nodes[queue[q]].right);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  const x = 1 + Math.floor(rand() * n);
  return [out, n, x];
}
